Can_Sync_Node* can_sync_node_free_create( void ) 
{
    Can_Sync_Node *can_sync_node = (Can_Sync_Node*)os_mem_request( sizeof( struct s_Can_Sync_Node ) ) ;

	if ( can_sync_node )
	{				
        out_set( (Out)(&(can_sync_node->can_sync_obj)) , (Out_Func)can_sync_tx_status );         
	} 

	return can_sync_node ;
}

